mapper.update:
update work_hour
position_id = #{positionId}, dept_id = #{deptId}, semester_id = #{semesterId}, work_date = #{workDate}, start_time = #{startTime}, end_time = #{endTime}, hours = #{hours}, work_content = #{workContent}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

update work_hour
status = 0, reject_reason = null, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select count(1)
from work_hour
where student_id = #{studentId}
  and work_date = #{workDate}
  and status != 3
  and start_time < #{endTime}
  and end_time > #{startTime}

    and id != #{excludeId}

select ifnull(sum(hours), 0)
from work_hour
where student_id = #{studentId}
  and status != 3
  and work_date >= #{startDate}
  and work_date <= #{endDate}

    and id != #{excludeId}

select wh.*,
       p.name as positionName,
       s.name as studentName,
       s.student_no as studentNo,
       d.name as deptName
from work_hour wh
left join position p on wh.position_id = p.id
left join student s on wh.student_id = s.id
left join dept d on wh.dept_id = d.id


        and wh.position_id = #{positionId}


        and wh.dept_id = #{deptId}


        and wh.semester_id = #{semesterId}


        and wh.status = #{status}


        and wh.student_id = #{studentId}


        and wh.work_date >= #{startDate}


        and wh.work_date <= #{endDate}


order by wh.work_date desc, wh.id desc
